
/* EduPlan AI 4.3: non-invasive learning workspace and auditable local activities */
(()=>{'use strict';
const VERSION='4.3',AUTHOR='Lê Bá Nhẫn – Trường THPT Hòn Đất';
const $=id=>document.getElementById(id), E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=x=>String(x??'').normalize('NFC').toLowerCase().replace(/\s+/g,' ').trim();
const bank=()=>window.EDP38?.bank?.()||window.EDP36?.questions?.()||[], lessons=()=>window.EDP38?.lessons?.()||window.EDP36?.lessons||[];
const key='edp43_workspace';let mem={},state={view:'home',role:'teacher',grade:'10',menu:false,filter:'',lesson:'',level:'all',current:null,selected:null,check:false,reflect:'',questionIndex:0,auditFilter:'all',records:[],replies:[],favorites:[],diagLesson:'',diag:null,diagnostics:[],plans:[],importedEvidence:[],simNotes:[],simPick:0,studentCode:'HS-01',largeText:false,highContrast:false,};
function load(){try{const o=JSON.parse(localStorage.getItem(key)||localStorage.getItem('edp42_workspace')||'{}');if(o&&typeof o==='object'){state.records=Array.isArray(o.records)?o.records.slice(-800):[];state.replies=Array.isArray(o.replies)?o.replies.slice(-300):[];state.favorites=Array.isArray(o.favorites)?o.favorites:[];state.diagnostics=Array.isArray(o.diagnostics)?o.diagnostics.slice(-240):[];state.plans=Array.isArray(o.plans)?o.plans.slice(-120):[];state.importedEvidence=Array.isArray(o.importedEvidence)?o.importedEvidence.slice(-300):[];state.simNotes=Array.isArray(o.simNotes)?o.simNotes.slice(-120):[];state.diag=o.diag&&typeof o.diag==='object'?o.diag:null;state.studentCode=ep43Code(o.studentCode);state.largeText=!!o.largeText;state.highContrast=!!o.highContrast}}catch(e){};state.role=window.EDP35?.getMode?.()||'teacher';state.grade=String($('grade')?.value||'10')}
function persist(){try{localStorage.setItem(key,JSON.stringify({records:state.records,replies:state.replies,favorites:state.favorites,diagnostics:state.diagnostics,plans:state.plans,importedEvidence:state.importedEvidence,simNotes:state.simNotes,diag:state.diag,studentCode:state.studentCode,largeText:state.largeText,highContrast:state.highContrast}));return true}catch(e){showToast('Trình duyệt không lưu được. Hãy tải bản sao JSON ngay.');return false}}
function showToast(s){let n=$('ep42-toast');if(n){n.textContent=s;n.hidden=false;clearTimeout(window.__ep42tm);window.__ep42tm=setTimeout(()=>n.hidden=true,4000)}}
function DL(name,contents,mime='application/json'){let u=URL.createObjectURL(new Blob([contents],{type:mime})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(u);a.remove()},1000)}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(s=>'"'+String(s??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
const teacher=()=>state.role==='teacher';const L=()=>lessons().filter(x=>String(x.g)===state.grade);const selectedLesson=()=>L().find(l=>l.id===state.lesson)||L()[0];
const levelNames=['Nhận biết','Thông hiểu','Vận dụng','Vận dụng cao'];
const styles=['','t2','t3','t4'];
const levelTag=x=>{let i=levelNames.indexOf(x);return `<span class="ep-chip ${styles[i]||''}">${E(x||'Chưa phân loại')}</span>`};
const TYPES={mcq:'I · Nhiều phương án',tf:'II · Đúng/Sai',short:'III · Trả lời ngắn',essay:'IV · Tự luận'};
const widgets=[
 {id:'diagnostic',icon:'🧭',name:'Chẩn đoán hai lượt',role:'student',cat:'học tập',desc:'Hai lượt câu hỏi khác nhau và phân tích kết quả.'},
 {id:'plan',icon:'🗓️',name:'Lộ trình hỗ trợ 7 ngày',role:'student',cat:'học tập',desc:'Kế hoạch theo mức còn yếu, tự ghi tiến độ.'},
 {id:'evidence',icon:'📥',name:'Sổ tiếp nhận bài tập',role:'teacher',cat:'đánh giá',desc:'Nhập kết quả, đánh dấu trạng thái và phản hồi.'},
 {id:'simlab',icon:'🧪',name:'Mô phỏng có nhiệm vụ',role:'both',cat:'học tập',desc:'PhET kèm phiếu dự đoán–quan sát–giải thích.'},
 {id:'fix',icon:'🧠',name:'Trạm sửa lỗi 3 bước',role:'both',cat:'học tập',desc:'Làm câu hỏi · đối chiếu lời giải · ghi lại nguyên nhân lỗi.'},
 {id:'audit',icon:'🔎',name:'Kiểm định ngân hàng',role:'teacher',cat:'đánh giá',desc:'Rà soát 576 câu theo đáp án, nguồn, lời giải, câu trùng.'},
 {id:'reflection',icon:'💬',name:'Phiếu phản tư 3–2–1',role:'both',cat:'học tập',desc:'Học sinh tự đánh giá; giáo viên nhập và tổng hợp phản hồi.'},
 {id:'ce',icon:'⚠️',name:'CHEM-ERROR ANALYZER',role:'teacher',cat:'chuyên sâu',desc:'Kiểm tra 11 nguồn, phân tích bước giải sai và xuất báo cáo.'},
 {id:'eduplan',icon:'📅',name:'Kế hoạch giáo dục',role:'teacher',cat:'soạn giảng',desc:'Tạo KHGD, chọn bài học và xuất Word.'},
 {id:'lab33',icon:'📑',name:'Xưởng KHBD phân hóa',role:'teacher',cat:'soạn giảng',desc:'Bốn hoạt động, bốn mức độ, phiếu học tập.'},
 {id:'exam34',icon:'📝',name:'Xưởng đề 18–4–6–4',role:'teacher',cat:'đánh giá',desc:'Tạo đề bốn phần, kiểm tra số câu thiếu, xuất DOCX.'},
 {id:'exam38',icon:'⏱️',name:'Phòng kiểm tra offline',role:'teacher',cat:'đánh giá',desc:'Gói đề và bài làm JSON, thời gian và chấm khách quan.'},
 {id:'class40',icon:'📺',name:'Điều hành tiết dạy',role:'teacher',cat:'soạn giảng',desc:'Kịch bản 45 phút và đồng hồ hỗ trợ hoạt động lớp.'},
 {id:'micro40',icon:'🎯',name:'Luyện nhanh sáu câu',role:'student',cat:'học tập',desc:'Luyện theo bài, nhận phản hồi và giải thích.'},
 {id:'insight40',icon:'📈',name:'Tiến bộ của em',role:'student',cat:'học tập',desc:'Xem tiến trình luyện tập theo mức độ.'},
 {id:'source38',icon:'📚',name:'Nguồn và độ phủ',role:'teacher',cat:'đánh giá',desc:'Xem nguồn đối chiếu và độ phủ mỗi bài.'},
 {id:'study35',icon:'📖',name:'Kiến thức cốt lõi',role:'student',cat:'học tập',desc:'Học theo chương, bài và dạng.'},
 {id:'assign39',icon:'📤',name:'Giao phiếu nhiệm vụ',role:'teacher',cat:'đánh giá',desc:'Xuất gói nhiệm vụ theo năng lực.'},
 {id:'study39',icon:'📥',name:'Nhiệm vụ của em',role:'student',cat:'học tập',desc:'Nhập và làm phiếu được giao.'},
 {id:'mark39',icon:'✅',name:'Phản hồi nhiệm vụ',role:'teacher',cat:'đánh giá',desc:'Chấm phần khách quan, nhận xét tự luận.'},
 {id:'mistakes39',icon:'🗒️',name:'Sổ tay lỗi sai',role:'student',cat:'học tập',desc:'Lưu lại câu khó, nguyên nhân và kế hoạch ôn.'},
 {id:'chem',icon:'⚗️',name:'Công cụ Hóa học',role:'teacher',cat:'chuyên sâu',desc:'Khối lượng mol, thành phần nguyên tố và kiểm tra nguyên tử.'}
];
function header(title,description,icon='⚗️',showActions=false){return `<div class="ep-hero"><div><div class="ep-eyebrow">EDUPLAN AI ${VERSION} · ${teacher()?'GIÁO VIÊN':'HỌC SINH'} · HÓA ${E(state.grade)}</div><h1>${E(title)}</h1><p>${E(description)}</p>${showActions?`<div class="ep-actions"><button class="ep-btn ep-hero-btn" onclick="EDP42.go('${teacher()?'audit':'fix'}')">${teacher()?'Kiểm định ngân hàng →':'Bắt đầu luyện sửa lỗi →'}</button><button class="ep-btn ep-ghost" onclick="EDP42.go('tools')">Khám phá công cụ</button></div>`:''}</div><div class="ep-hero-icon" aria-hidden="true">${icon}</div></div>`}
const panel=(title,content,sub='')=>`<section class="ep-panel"><h2>${E(title)}</h2>${sub?`<p>${E(sub)}</p>`:''}${content}</section>`;
function toolsList(query='',cat='all'){let q=norm(query);return widgets.filter(w=>(w.role==='both'||w.role===state.role)&&(cat==='all'||w.cat===cat)&&norm(w.name+' '+w.desc).includes(q));}
const cards=(arr)=>`<div class="ep-cardgrid">${arr.map(w=>`<button class="ep-card" onclick="EDP42.launch('${w.id}')"><span class="ep-card-icon">${w.icon}</span><strong>${E(w.name)}</strong><small>${E(w.desc)}</small><span class="ep-open">Mở chức năng →</span></button>`).join('')||'<p>Không tìm thấy công cụ phù hợp.</p>'}</div>`;
function kpis(){const b=bank().filter(q=>String(q.g)===state.grade),ls=L(),used=state.records.filter(r=>r.grade===state.grade);let valid=new Set(used.map(x=>x.id));let complete=ls.filter(l=>{const qs=b.filter(q=>q.lessonId===l.id);return ['mcq','tf','short','essay'].every((t,i)=>qs.filter(q=>q.type===t).length>=[18,4,6,4][i])}).length;return `<div class="ep-kpis"><div class="ep-kpi"><b>${b.length}</b><span>Câu Hóa ${E(state.grade)}</span></div><div class="ep-kpi"><b>${ls.length}</b><span>Bài trong thư viện</span></div><div class="ep-kpi"><b>${complete}/${ls.length}</b><span>Bài đủ cấu trúc 18–4–6–4</span></div><div class="ep-kpi"><b>${teacher()?state.replies.filter(x=>x.grade===state.grade).length:valid.size}</b><span>${teacher()?'Phiếu phản tư trên thiết bị':'Câu đã luyện sửa lỗi'}</span></div></div>`}
function home(){let suggest=teacher()?['lab33','exam34','audit','ce']:['study35','fix','micro40','reflection'];return header(teacher()?'Trung tâm giảng dạy Hóa học':'Không gian học Hóa của em',teacher()?'Chuẩn bị – tổ chức – kiểm tra – đánh giá trong một nơi; công cụ cũ vẫn được giữ nguyên.':'Học theo bài, tìm ra chỗ chưa hiểu, tự sửa lỗi và biết nhiệm vụ tiếp theo.','⚗️',true)+kpis()+ep43HomeQuick()+`<div class="ep-layout"><div>${panel('Việc cần làm ngay',cards(suggest.map(id=>widgets.find(w=>w.id===id)).filter(Boolean)),'Chọn một tác vụ để bắt đầu. Menu tự ẩn khi bạn chọn chức năng.')}${panel('Tra cứu nhanh',`<input class="ep-search" id="epSearchHome" placeholder="Tìm công cụ, ví dụ: trộn đề, phiếu học tập..." oninput="EDP42.search(this.value)" aria-label="Tìm kiếm công cụ"><div id="epSearchCards">${cards(toolsList().slice(0,6))}</div>`)}</div><div>${panel('Chu trình học tập',`<div class="ep-links"><button class="ep-btn" onclick="EDP42.launch('study35')">1 · Kiến thức bài học</button><button class="ep-btn" onclick="EDP42.go('fix')">2 · Luyện và sửa lỗi</button><button class="ep-btn" onclick="EDP42.launch('micro40')">3 · Kiểm tra nhanh</button><button class="ep-btn" onclick="EDP42.go('reflection')">4 · Tự phản tư</button></div>`)}${panel('Nguồn tham khảo mở',`<div class="ep-links"><a class="ep-link" href="https://phet.colorado.edu/" target="_blank" rel="noopener noreferrer">PhET – Mô phỏng Hóa học ↗</a><a class="ep-link" href="https://openstax.org/books/chemistry-2e/pages/1-introduction" target="_blank" rel="noopener noreferrer">OpenStax – Chemistry 2e ↗</a><a class="ep-link" href="https://www.khanacademy.org/science/chemistry" target="_blank" rel="noopener noreferrer">Khan Academy – Chemistry ↗</a></div><p class="ep-mini">Liên kết học liệu mở; không tự động nhập dữ liệu học sinh ra ngoài.</p>`)}</div></div>`}
function tools(){return header('Thư viện công cụ', 'Tìm nhanh theo nhiệm vụ, không cần cuộn menu nhiều tầng.','🧰')+panel('Tìm công cụ',`<div class="ep-formrow"><label class="ep-field">Tên hoặc nội dung chức năng<input value="${E(state.filter)}" id="epToolSearch" oninput="EDP42.toolSearch(this.value)" placeholder="Ví dụ: KHBD, chấm bài, lỗi sai"></label><label class="ep-field">Nhóm công việc<select id="epCat" onchange="EDP42.toolCategory(this.value)"><option value="all">Tất cả</option>${['học tập','soạn giảng','đánh giá','chuyên sâu'].map(c=>`<option value="${E(c)}" ${state.category===c?'selected':''}>${E(c)}</option>`).join('')}</select></label></div><div id="epToolCards">${cards(toolsList(state.filter,state.category||'all'))}</div>`)}
function qList(){let l=selectedLesson();return bank().filter(q=>q.g===state.grade&&q.lessonId===l?.id&&q.type==='mcq'&&q.ops?.length===4&&Number.isInteger(q.ans)&&q.ans>=0&&q.ans<4&&q.exp).sort((a,b)=>levelNames.indexOf(a.lv)-levelNames.indexOf(b.lv)).filter(q=>state.level==='all'||q.lv===state.level)}
function question(){let q=state.current;return q?`<div class="ep-levels">${levelTag(q.lv)}<span class="ep-chip">${E(q.id)}</span><span class="ep-chip">Phần I</span></div><h3 style="margin:10px 0;font-size:17px;color:#243c60">${E(q.stem)}</h3><div class="ep-quizopts">${q.ops.map((o,i)=>`<label class="ep-opt"><input type="radio" name="ep42answer" value="${i}" ${state.selected===i?'checked':''} ${state.check?'disabled':''} onchange="EDP42.answer(${i})"><span><b>${'ABCD'[i]}.</b> ${E(o)}</span></label>`).join('')}</div>${state.check?feedback(q):`<button class="ep-btn ep-primary" ${state.selected===null?'disabled':''} onclick="EDP42.check()">Kiểm tra câu trả lời</button>`}`:'<div class="ep-info">Chọn bài học và nhấn “Bắt đầu luyện” để nhận câu hỏi.</div>'}
function feedback(q){const right=state.selected===q.ans;return `<div class="ep-result ${right?'ep-success':'ep-error'}"><strong>${right?'✓ Chính xác!':'✕ Chưa đúng – hãy tìm nguyên nhân'}</strong><p><b>Đáp án:</b> ${'ABCD'[q.ans]}. ${E(q.ops[q.ans])}</p><p><b>Giải thích:</b> ${E(q.exp)}</p><p class="ep-mini">Nguồn đối chiếu: ${q.src&&/^https:\/\//.test(q.src)?`<a href="${E(q.src)}" target="_blank" rel="noopener noreferrer">Mở tài liệu tham khảo ↗</a>`:E(q.source||'Chưa có liên kết')}. Nội dung chờ giáo viên thẩm định.</p><label class="ep-field">Bước tiếp theo: chọn nguyên nhân để ghi sổ tay<select id="ep42cause"><option value="nhầm khái niệm">Nhầm khái niệm/bản chất</option><option value="đọc thiếu dữ kiện">Đọc thiếu dữ kiện, điều kiện</option><option value="tính toán hoặc ký hiệu">Sai tính toán/ký hiệu</option><option value="chưa nhớ quy tắc">Chưa nhớ quy tắc/định luật</option><option value="cần giáo viên giải thích">Cần giáo viên giải thích thêm</option><option value="đã nắm vững">Đã nắm vững</option></select></label><div class="ep-actions"><button class="ep-btn ep-primary" onclick="EDP42.saveError()">Lưu phản tư & câu tiếp theo →</button></div></div>`}
function fix(){let l=selectedLesson(),pool=qList(),records=state.records.filter(r=>r.grade===state.grade);return header('Trạm sửa lỗi Hóa học – 3 bước','Bước 1: chọn đáp án · Bước 2: đọc giải thích đã có · Bước 3: tự xác định nguyên nhân.','🧠')+`<div class="ep-layout"><div>${panel('Luyện sửa lỗi có hướng dẫn',`<div class="ep-formrow"><label class="ep-field">Chọn bài học<select id="ep42lesson" onchange="EDP42.lesson(this.value)">${L().map(x=>`<option value="${E(x.id)}" ${l?.id===x.id?'selected':''}>${E(x.title)}</option>`).join('')}</select></label><label class="ep-field">Mức độ nhận thức<select id="ep42level" onchange="EDP42.level(this.value)"><option value="all">Tất cả các mức</option>${levelNames.map(x=>`<option value="${E(x)}" ${state.level===x?'selected':''}>${E(x)}</option>`).join('')}</select></label></div><p class="ep-info">Ngân hàng phù hợp: <b>${pool.length}</b> câu Phần I của bài “${E(l?.title||'')}”. Câu tự luận cần giáo viên nhận xét.</p><div class="ep-actions"><button class="ep-btn ep-turquoise" onclick="EDP42.newQuiz()">${state.current?'Lấy câu khác':'Bắt đầu luyện'}</button></div><div id="ep42Q">${question()}</div>`)}${panel('Nhật ký sửa lỗi trên thiết bị',records.length?`<div class="ep-table-wrap"><table><thead><tr><th>Thời điểm</th><th>Mã câu</th><th>Kết quả</th><th>Nguyên nhân tự chọn</th></tr></thead><tbody>${records.slice(-10).reverse().map(r=>`<tr><td>${E(new Date(r.at).toLocaleDateString('vi-VN'))}</td><td>${E(r.id)}</td><td>${r.right?'Đúng':'Sai'}</td><td>${E(r.cause)}</td></tr>`).join('')}</tbody></table></div><button class="ep-btn" onclick="EDP42.exportJournal()">Xuất nhật ký CSV</button>`:'<p>Chưa có dữ liệu. Làm một câu để bắt đầu ghi nhận lỗi sai.</p>')}</div><div>${panel('Phương pháp 3 bước',`<div class="ep-info"><b>01 · Trả lời:</b> Chọn một phương án trước khi xem lời giải.</div><div class="ep-info"><b>02 · Giải thích:</b> Xác định kiến thức/chỗ hiểu chưa đúng.</div><div class="ep-info"><b>03 · Phản tư:</b> Tự ghi nguyên nhân để lập kế hoạch ôn tập.</div><div class="ep-warning">Không tự kết luận “bước sai đầu tiên” khi chưa có lời giải từng bước của học sinh; các nhận xét chỉ mang tính hướng dẫn.</div>`)}</div></div>`}
function inspectBank(){const b=bank(), cnt=new Map(), issues=[];for(const q of b){let flags=[];if(!q.stem?.trim())flags.push('Thiếu nội dung');if(!q.exp?.trim())flags.push('Thiếu giải thích');if(!q.src&&!q.reference_url)flags.push('Thiếu URL nguồn');if(q.type==='mcq'&&(!Array.isArray(q.ops)||q.ops.length!==4||!Number.isInteger(q.ans)||q.ans<0||q.ans>3))flags.push('Đáp án/phương án chưa hợp lệ');if(q.type==='tf'&&(!Array.isArray(q.ops)||q.ops.length!==4||!Array.isArray(q.ans)||q.ans.length!==4||q.ans.some(x=>typeof x!=='boolean')))flags.push('Đúng/Sai chưa đủ 4 ý');if(q.type==='essay'&&!q.rubric?.length)flags.push('Tự luận chưa có rubric');if(!q.review||!/thẩm định|kiểm định|chờ|phản biện/i.test(q.review))flags.push('Chưa rõ trạng thái thẩm định');const id=q.id||'';cnt.set(id,(cnt.get(id)||0)+1);issues.push({q,flags})}for(const x of issues)if(cnt.get(x.q.id)>1)x.flags.push('Trùng mã câu');return issues}
function audit(){let all=inspectBank(),b=all.filter(x=>x.q.g===state.grade),flag=b.filter(x=>x.flags.length),valid=b.length-flag.length,gradeLesson=L(),cnt={};for(let q of b){let k=q.q.lessonId;cnt[k]??={mcq:0,tf:0,short:0,essay:0};cnt[k][q.q.type]=(cnt[k][q.q.type]||0)+1}let filtered=b.filter(x=>state.auditFilter==='all'||(state.auditFilter==='issue'?x.flags.length:!x.flags.length));return header('Kiểm định dữ liệu ngân hàng','Kiểm tra tự động về cấu trúc, không thay thế việc phản biện đáp án và tính đúng đắn Hóa học.','🔎')+kpis()+panel('Bảng kiểm dữ liệu',`<div class="ep-kpis"><div class="ep-kpi"><b>${b.length}</b><span>Tổng câu khối ${E(state.grade)}</span></div><div class="ep-kpi"><b>${valid}</b><span>Không phát hiện thiếu trường cấu trúc</span></div><div class="ep-kpi"><b>${flag.length}</b><span>Câu cần kiểm tra trường dữ liệu</span></div><div class="ep-kpi"><b>${b.filter(x=>x.q.review&&!/đã được giáo viên kiểm định/i.test(x.q.review)).length}</b><span>Chưa có xác nhận kiểm định độc lập</span></div></div><div class="ep-warning">“Không có lỗi cấu trúc” KHÔNG đồng nghĩa câu hỏi khoa học đúng hoặc đã được duyệt. Chưa có quy trình xác thực đáp án độc lập trong bản này.</div><div class="ep-actions"><button class="ep-btn ep-primary" onclick="EDP42.exportAudit()">Xuất báo cáo CSV</button><label class="ep-field" style="margin:0">Lọc danh sách<select onchange="EDP42.auditFilter(this.value)"><option value="all">Tất cả</option><option value="issue" ${state.auditFilter==='issue'?'selected':''}>Cần kiểm tra</option><option value="clean" ${state.auditFilter==='clean'?'selected':''}>Đủ trường dữ liệu</option></select></label></div><div class="ep-table-wrap" style="max-height:360px;overflow:auto"><table><thead><tr><th>Mã câu</th><th>Bài học</th><th>Phần</th><th>Mức</th><th>Cảnh báo</th></tr></thead><tbody>${filtered.slice(0,120).map(x=>`<tr><td>${E(x.q.id)}</td><td>${E(x.q.lesson)}</td><td>${E(TYPES[x.q.type]||x.q.type)}</td><td>${levelTag(x.q.lv)}</td><td>${x.flags.length?E(x.flags.join('; ')):'Đủ trường'}</td></tr>`).join('')}</tbody></table></div>`)+panel('Độ phủ 18–4–6–4 theo bài',`<div class="ep-table-wrap"><table><thead><tr><th>Bài</th><th>Phần I</th><th>II</th><th>III</th><th>IV</th><th>Trạng thái</th></tr></thead><tbody>${gradeLesson.map(l=>{let c=cnt[l.id]||{mcq:0,tf:0,short:0,essay:0};let good=c.mcq>=18&&c.tf>=4&&c.short>=6&&c.essay>=4;return `<tr><td>${E(l.title)}</td><td>${c.mcq}/18</td><td>${c.tf}/4</td><td>${c.short}/6</td><td>${c.essay}/4</td><td>${good?'Đủ số lượng':'Thiếu câu'}</td></tr>`}).join('')}</tbody></table></div>`) }
const threeLines=x=>x.split('\n').map(y=>y.trim()).filter(Boolean);
function reflection(){const arr=state.replies.filter(r=>r.grade===state.grade);let h=teacher()?panel('Tổng hợp phản tư trên máy giáo viên',`<div class="ep-info">Học sinh xuất tệp JSON rồi giáo viên nhập thủ công. Không có đồng bộ tự động qua Internet.</div><div class="ep-actions"><label class="ep-btn ep-primary">Nhập phản hồi JSON<input type="file" id="ep42Import" accept=".json,application/json" multiple onchange="EDP42.importReplies(this.files)" style="display:none"></label><button class="ep-btn" onclick="EDP42.exportRepliesCSV()">Xuất báo cáo CSV</button></div>${arr.length?`<div class="ep-table-wrap"><table><tr><th>Ngày</th><th>Bài</th><th>3 điều đã học</th><th>2 điều chưa rõ</th><th>1 câu hỏi</th></tr>${arr.slice(-40).reverse().map(r=>`<tr><td>${E(r.date)}</td><td>${E(r.lesson)}</td><td>${E(r.know.join('; '))}</td><td>${E(r.confusing.join('; '))}</td><td>${E(r.question)}</td></tr>`).join('')}</table></div>`:'<p>Chưa có phản hồi được nhập.</p>'}`):panel('Viết phiếu phản tư sau giờ học',`<div class="ep-info"><b>3–2–1:</b> Viết ba điều đã hiểu; hai điều còn băn khoăn; một câu hỏi muốn giáo viên giải đáp. Không nhập họ tên thật hoặc dữ liệu nhạy cảm.</div><label class="ep-field">Bài học<select id="ep42rfLesson">${L().map(l=>`<option value="${E(l.id)}">${E(l.title)}</option>`).join('')}</select></label><label class="ep-field">Ba điều em đã học được (mỗi dòng một ý)<textarea id="ep42rfKnow" rows="4" placeholder="1. ...\n2. ...\n3. ..." maxlength="1200"></textarea></label><label class="ep-field">Hai điều em chưa chắc (mỗi dòng một ý)<textarea id="ep42rfConf" rows="3" placeholder="1. ...\n2. ..." maxlength="850"></textarea></label><label class="ep-field">Một câu hỏi dành cho giáo viên<textarea id="ep42rfQuestion" rows="2" maxlength="350" placeholder="Em muốn hỏi..."></textarea></label><button class="ep-btn ep-primary" onclick="EDP42.saveReflection()">Lưu và tải phiếu JSON</button>`);return header('Phản tư cuối tiết 3–2–1','Hoạt động phản hồi ngắn gọn, giúp giáo viên nhận biết nội dung học sinh còn băn khoăn.','💬')+h}
/* EduPlan AI 4.3 - daily learning, two-round diagnosis, responsible evidence import */
function ep43HomeQuick(){const own=state.diagnostics.filter(x=>x.grade===state.grade&&x.code===state.studentCode);const recent=own[own.length-1];return `<div class="ep43-intro"><div><b>${teacher()?'Hôm nay thầy/cô cần làm gì?':'Hôm nay em học gì?'}</b><p>${teacher()?'Giao nhiệm vụ, theo dõi kết quả nhận được và lên kế hoạch hỗ trợ từ bằng chứng đã nộp.':'Bắt đầu từ bài chẩn đoán; luyện lượt hai bằng câu chưa gặp, sau đó lập kế hoạch 7 ngày.'}</p></div><div class="ep43-actions"><button class="ep-btn ep-primary" onclick="EDP42.go('${teacher()?'evidence':'diagnostic'}')">${teacher()?'Mở sổ tiếp nhận bài':'Bài chẩn đoán hai lượt'}</button><button class="ep-btn" onclick="EDP42.go('${teacher()?'simlab':'plan'}')">${teacher()?'Mô phỏng có nhiệm vụ':'Kế hoạch ôn 7 ngày'}</button><button class="ep-btn" onclick="EDP42.backup43()">Sao lưu</button></div></div>${recent&&!teacher()?`<div class="ep-info">Kết quả gần đây của mã ${E(state.studentCode)}: ${recent.correct}/${recent.total} câu · ${E(recent.lesson)}. Số câu ít, chưa thể kết luận năng lực.</div>`:''}`}
const ep43Levels=['Nhận biết','Thông hiểu','Vận dụng','Vận dụng cao'];
const ep43EvidenceSchema='EduPlan43_Evidence_v1';
function ep43Code(v){let code=String(v||'').trim().toUpperCase().replace(/[^A-Z0-9_-]/g,'').slice(0,18);return code||'HS-01'}
function ep43Lesson(){return L().find(l=>l.id===state.diagLesson)||L()[0]}
function ep43Pool(lesson){return bank().filter(q=>String(q.g)===state.grade&&q.lessonId===lesson&&q.type==='mcq'&&Array.isArray(q.ops)&&q.ops.length===4&&Number.isInteger(q.ans)&&q.ans>=0&&q.ans<4&&typeof q.stem==='string'&&q.stem.trim())}
function ep43Select(pool,n){let a=[...pool];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a.slice(0,n)}
function ep43RoundHtml(){const d=state.diag;if(!d)return '';let pool=bank(),items=d.ids.map(id=>pool.find(q=>q.id===id)).filter(Boolean);let cnt=items.filter(q=>Object.hasOwn(d.answers,q.id)).length;let answered=cnt===items.length;let h=`<div class="ep43-pills"><span class="ep43-pill">Lượt ${d.stage}/2</span><span class="ep43-pill">Đã trả lời ${cnt}/${items.length}</span><span class="ep43-pill">${E(state.studentCode)}</span></div><div class="ep-meter" aria-label="Tiến độ làm bài"><span style="width:${Math.round(100*cnt/Math.max(1,items.length))}%"></span></div>`;
if(d.finished){let r=state.diagnostics.find(x=>x.id===d.resultId);h+=`<div class="ep-result ${r?.correct>=4?'ep-success':''}"><b>Đã nộp lượt ${d.stage}</b> · ${r?.correct??0}/${items.length} câu đúng. Đây chỉ là phản hồi luyện tập theo quy tắc, chưa phải đánh giá năng lực chuẩn hóa.</div>`}
items.forEach((q,i)=>{let chosen=d.answers[q.id];let reveal=d.finished;h+=`<section class="ep43-question"><div class="ep43-qhead">Câu ${i+1} ${levelTag(q.lv)} <small>${E(q.id)}</small></div><div>${E(q.stem)}</div><div class="ep43-opts">${q.ops.map((op,j)=>`<label class="ep43-choice ${reveal?(j===q.ans?'ep43-correct':chosen===j?'ep43-incorrect':''):''}"><input type="radio" name="ep43_${E(q.id)}" value="${j}" ${chosen===j?'checked':''} ${reveal?'disabled':''} onchange="EDP42.diagAnswer('${E(q.id)}',${j})"> <span><b>${'ABCD'[j]}.</b> ${E(op)}</span></label>`).join('')}</div>${reveal?`<details class="ep43-explain"><summary>Đáp án và lời giải đã có trong ngân hàng</summary><b>Đáp án ${'ABCD'[q.ans]}.</b> ${E(q.exp||'Chưa có giải thích; cần giáo viên bổ sung.')}${q.src||q.reference_url?`<div class="ep-mini">Nguồn đối chiếu: ${E(q.src||q.reference_url)}</div>`:''}</details>`:''}</section>`});
if(!d.finished)h+=`<button id="ep43submit" class="ep-btn ep-primary" onclick="EDP42.diagSubmit()" ${!answered?'disabled':''}>Nộp lượt ${d.stage}${!answered?' · trả lời đủ câu để nộp':''}</button>`;
else if(d.stage===1)h+=`<button class="ep-btn ep-primary" onclick="EDP42.diagNext()">Luyện lượt hai bằng câu CHƯA gặp →</button>`;
else h+=`<div class="ep43-actions"><button class="ep-btn ep-primary" onclick="EDP42.go('plan')">Lập lộ trình củng cố 7 ngày</button><button class="ep-btn" onclick="EDP42.diagExport()">Xuất kết quả JSON để gửi giáo viên</button><button class="ep-btn" onclick="EDP42.diagStart()">Bắt đầu vòng mới</button></div>`;
return h}
function ep43Diagnostic(){let lesson=ep43Lesson(),pool=ep43Pool(lesson?.id);const prev=state.diagnostics.filter(x=>x.grade===state.grade&&x.code===state.studentCode&&x.lessonId===lesson?.id);return header('Chẩn đoán hai lượt – không lặp câu','Học sinh làm hai lượt, mỗi lượt sáu câu khác nhau. So sánh chỉ mang tính tham khảo nếu không có hai bộ đề tương đương đã kiểm định.','🧭')+panel('Chọn bài và mã học tập',`<div class="ep-formrow"><label class="ep-field">Mã học tập giả lập (không nhập tên thật)<input maxlength="18" id="ep43Code" value="${E(state.studentCode)}" onchange="EDP42.setStudyCode(this.value)" placeholder="HS-01"></label><label class="ep-field">Bài học<select id="ep43Lesson" onchange="EDP42.diagLesson(this.value)">${L().map(l=>`<option value="${E(l.id)}" ${lesson?.id===l.id?'selected':''}>${E(l.title)}</option>`).join('')}</select></label></div><div class="ep-info">Bài được chọn hiện có <b>${pool.length}</b> câu Phần I có đáp án hợp lệ về cấu trúc. Cần tối thiểu 12 câu khác nhau để làm hai lượt 6 câu. Mỗi câu vẫn phải được giáo viên thẩm định về chuyên môn.</div><div class="ep43-actions"><button class="ep-btn ep-primary" onclick="EDP42.diagStart()" ${pool.length<12?'disabled':''}>Bắt đầu chẩn đoán lượt 1</button><button class="ep-btn" onclick="EDP42.go('plan')">Xem kế hoạch hỗ trợ</button></div>${pool.length<12?`<div class="ep-warning">Không đủ 12 câu độc lập ở bài này. Hãy chọn bài đã có đủ câu hoặc bổ sung ngân hàng, không tự nhân bản câu.</div>`:''}`)+panel('Bài luyện đang thực hiện',state.diag&&state.diag.grade===state.grade&&state.diag.lessonId===lesson?.id?ep43RoundHtml():`<p>Chưa có bài đang làm. Chọn một bài đủ câu để bắt đầu.</p>`)+panel('Nhật ký lượt làm (cùng mã và bài)',prev.length?`<div class="ep-table-wrap"><table><tr><th>Lượt</th><th>Ngày</th><th>Kết quả</th><th>Số mã câu</th></tr>${prev.slice(-8).reverse().map(r=>`<tr><td>${r.stage}</td><td>${E(String(r.at).slice(0,10))}</td><td>${r.correct}/${r.total}</td><td>${r.items.length}</td></tr>`).join('')}</table></div>`:'<p>Chưa có lượt hoàn thành.</p>')}
const ep43TaskBase=[
 'Đọc lại mục tiêu bài học và xác định ba khái niệm cốt lõi.',
 'Lập bảng hai cột: điều đã hiểu và điều còn nhầm lẫn.',
 'Làm ba câu Nhận biết/Thông hiểu chưa gặp, đối chiếu nguồn.',
 'Viết lời giải một bài Vận dụng, nêu rõ bước bảo toàn.',
 'Chọn một lỗi sai điển hình và giải lại bằng cách khác.',
 'Tự giải thích bài cho bạn học bằng 5–7 câu ngắn.',
 'Làm lại câu mới và ghi nhận phần đã tiến bộ/chưa vững.'
];
function ep43PlanKey(){return [state.grade,ep43Lesson()?.id,state.studentCode].join('|')}
function ep43Plan(){const l=ep43Lesson(),k=ep43PlanKey(),p=state.plans.find(x=>x.key===k),recent=state.diagnostics.filter(x=>x.code===state.studentCode&&x.grade===state.grade&&x.lessonId===l?.id),distinct=new Set(recent.flatMap(r=>r.items.map(q=>q.id))),all=recent.flatMap(r=>r.items),weak=ep43Levels.map(lv=>({lv,n:all.filter(x=>x.lv===lv).length,correct:all.filter(x=>x.lv===lv&&x.right).length})).filter(x=>x.n>0).sort((a,b)=>a.correct/a.n-b.correct/b.n);let clue=weak[0]?.lv||'Chưa đủ dữ liệu';let check=p?.done?.filter(Boolean).length||0;return header('Lộ trình hỗ trợ học tập 7 ngày','Một chuỗi nhiệm vụ có thể chỉnh sửa theo bài học; không gán nhãn năng lực chỉ từ vài câu.','🗓️')+panel('Kế hoạch cá nhân trên thiết bị',`<div class="ep-formrow"><label class="ep-field">Mã học tập<input value="${E(state.studentCode)}" onchange="EDP42.setStudyCode(this.value)" maxlength="18"></label><label class="ep-field">Chọn bài<select onchange="EDP42.diagLesson(this.value)">${L().map(x=>`<option value="${E(x.id)}" ${l?.id===x.id?'selected':''}>${E(x.title)}</option>`).join('')}</select></label></div><div class="ep-info">Bằng chứng: <b>${distinct.size} mã câu khác nhau</b>; ${recent.length} lượt đã ghi · Mức ưu tiên tham khảo: <b>${E(clue)}</b>. ${distinct.size<12?'Chưa đủ dữ liệu để kết luận mức độ vững kiến thức.':'Có thể tham khảo xu hướng, nhưng vẫn cần đối chiếu đánh giá của giáo viên.'}</div><div class="ep43-actions"><button class="ep-btn ep-primary" onclick="EDP42.planBuild()">${p?'Cập nhật nhiệm vụ':'Tạo kế hoạch 7 ngày'}</button>${p?'<button class="ep-btn" onclick="EDP42.planExport()">Xuất kế hoạch CSV</button>':''}</div>`)+panel('Nhiệm vụ theo ngày',p?`<div class="ep-meter"><span style="width:${Math.round(check/7*100)}%"></span></div><p>Đã hoàn thành ${check}/7 nhiệm vụ. Đây là việc học tự ghi nhận, chưa có xác thực của giáo viên.</p><div class="ep43-tasks">${p.tasks.map((s,i)=>`<label class="ep43-task"><input type="checkbox" ${p.done[i]?'checked':''} onchange="EDP42.planCheck(${i},this.checked)"><span><strong>Ngày ${i+1}</strong> ${E(s)}</span></label>`).join('')}</div>`:'<p>Chưa có kế hoạch. Nhấn “Tạo kế hoạch 7 ngày” để bắt đầu.</p>')}
function ep43EvidenceRows(){let list=state.importedEvidence.filter(e=>e.grade===state.grade);return list.length?`<div class="ep-table-wrap"><table><thead><tr><th>Mã</th><th>Bài</th><th>Lượt</th><th>Điểm khách quan</th><th>Trạng thái</th><th>Nhận xét</th></tr></thead><tbody>${list.slice(-200).reverse().map(e=>`<tr><td>${E(e.code)}</td><td>${E(e.lesson)}</td><td>${e.rounds.length}</td><td>${e.rounds.map(x=>x.correct+'/'+x.total).join(' → ')}</td><td><select aria-label="Trạng thái đánh giá" onchange="EDP42.evidenceStatus('${E(e.id)}',this.value)">${['Đã nhận','Cần xem lại','Cần hỗ trợ','Đã phản hồi'].map(x=>`<option ${x===e.status?'selected':''}>${x}</option>`).join('')}</select></td><td><input aria-label="Nhận xét giáo viên" maxlength="240" value="${E(e.note||'')}" onchange="EDP42.evidenceNote('${E(e.id)}',this.value)" placeholder="Ghi nhận xét..."></td></tr>`).join('')}</tbody></table></div>`:'<p>Chưa nhập kết quả từ học sinh.</p>'}
function ep43Evidence(){let n=state.importedEvidence.filter(x=>x.grade===state.grade),code=new Set(n.map(x=>x.code)).size;return header('Sổ tiếp nhận và phản hồi học tập','Nhập kết quả JSON học sinh gửi, kiểm tra cấu trúc và đánh dấu tình trạng hỗ trợ; không có đồng bộ trực tuyến.','📥')+`<div class="ep-kpis"><div class="ep-kpi"><b>${n.length}</b><span>Tệp kết quả khối ${E(state.grade)}</span></div><div class="ep-kpi"><b>${code}</b><span>Mã học tập khác nhau</span></div><div class="ep-kpi"><b>${n.filter(x=>x.status==='Cần hỗ trợ').length}</b><span>Cần hỗ trợ</span></div><div class="ep-kpi"><b>${n.filter(x=>x.status==='Đã phản hồi').length}</b><span>Đã phản hồi</span></div></div>`+panel('Nhập và xuất bằng chứng',`<div class="ep-warning">Chỉ dùng mã học sinh giả lập. Tệp JSON có thể bị chỉnh sửa; đây là minh chứng luyện tập, không phải hệ thống xác thực kỳ thi. Giáo viên xem và thẩm định trước khi nhận xét.</div><div class="ep43-actions"><label class="ep-btn ep-primary">Nhập tệp JSON học sinh <input type="file" accept=".json,application/json" multiple hidden onchange="EDP42.evidenceImport(this.files)"></label><button class="ep-btn" onclick="EDP42.evidenceCSV()">Xuất sổ CSV</button><button class="ep-btn" onclick="EDP42.backup43()">Sao lưu dữ liệu 4.3</button><label class="ep-btn">Khôi phục dữ liệu 4.3<input type="file" accept=".json,application/json" hidden onchange="EDP42.restore43(this.files[0])"></label></div>`)+panel('Kết quả đã nhập và phản hồi',ep43EvidenceRows())}
const ep43Sims=[
 {name:'Xây dựng nguyên tử',grade:'10',url:'https://phet.colorado.edu/en/simulations/build-an-atom',question:'Thay đổi số proton và electron. Ghi lại Z, điện tích hạt và giải thích sự khác nhau giữa nguyên tử và ion.'},
 {name:'Cân bằng phương trình Hóa học',grade:'10',url:'https://phet.colorado.edu/en/simulations/balancing-chemical-equations',question:'Quan sát số nguyên tử hai vế, điều chỉnh hệ số rồi giải thích vì sao không thay đổi chỉ số nguyên tử trong công thức.'},
 {name:'Dung dịch acid và base',grade:'11',url:'https://phet.colorado.edu/en/simulations/acid-base-solutions',question:'So sánh hai dung dịch cùng nồng độ có độ mạnh acid khác nhau. Quan sát dạng tồn tại của các tiểu phân và liên hệ độ điện li.'},
 {name:'Thang đo pH cơ bản',grade:'11',url:'https://phet.colorado.edu/vi/simulations/ph-scale-basics',question:'Dự đoán ảnh hưởng của sự pha loãng đến pH, sau đó quan sát kết quả mô phỏng và đối chiếu giả thuyết.'},
 {name:'Cấu trúc nguyên tử – ôn nền tảng',grade:'12',url:'https://phet.colorado.edu/en/simulations/build-an-atom',question:'Nhận diện proton, electron, cấu trúc ion. Liên hệ với số oxi hóa và khả năng tạo ion trong phản ứng điện hóa.'}
];
function ep43Sim(){const sims=ep43Sims.filter(s=>s.grade===state.grade);const notes=state.simNotes.filter(x=>x.grade===state.grade);return header('Phòng mô phỏng Hóa học có nhiệm vụ','Mở mô phỏng nghiên cứu ngoài trang, dự đoán – quan sát – giải thích và lưu phiếu học tập.','🧪')+panel('Chọn hoạt động từ thư viện PhET',`<div class="ep-cardgrid">${sims.map((x,i)=>`<div class="ep43-simcard"><b>${E(x.name)}</b><p>${E(x.question)}</p><a class="ep-btn ep-primary" href="${E(x.url)}" target="_blank" rel="noopener noreferrer">Mở mô phỏng PhET ↗</a><button class="ep-btn" onclick="EDP42.simChoose(${i})">Viết phiếu quan sát</button></div>`).join('')}</div><div class="ep-warning">Mô phỏng do PhET vận hành, cần Internet để mở liên kết. EduPlan AI không lưu kết quả trực tiếp từ PhET hoặc tự suy luận những gì em đã quan sát.</div>`)+panel('Phiếu Dự đoán → Quan sát → Giải thích',`<label class="ep-field">Hoạt động<select id="ep43SimPick">${sims.map((x,i)=>`<option value="${i}" ${state.simPick===i?'selected':''}>${E(x.name)}</option>`).join('')}</select></label><label class="ep-field">Em dự đoán điều gì?<textarea id="ep43Predict" maxlength="1200" placeholder="Nêu giả thuyết trước khi chạy mô phỏng..."></textarea></label><label class="ep-field">Em quan sát được gì?<textarea id="ep43Observe" maxlength="1200" placeholder="Ghi đúng kết quả quan sát..."></textarea></label><label class="ep-field">Em giải thích bằng kiến thức Hóa học như thế nào?<textarea id="ep43Explain" maxlength="1400" placeholder="Lập luận, so sánh với dự đoán..."></textarea></label><button class="ep-btn ep-primary" onclick="EDP42.simSave()">Lưu và xuất phiếu JSON</button>`)+panel('Phiếu mô phỏng đã lưu',notes.length?`<div class="ep-table-wrap"><table><tr><th>Ngày</th><th>Hoạt động</th><th>Giải thích</th></tr>${notes.slice(-12).reverse().map(x=>`<tr><td>${E(x.at.slice(0,10))}</td><td>${E(x.name)}</td><td>${E(x.explain.slice(0,180))}</td></tr>`).join('')}</table></div>`:'<p>Chưa lưu phiếu quan sát.</p>')}
function ep43ApplyAppearance(){const n=$('ep42');if(!n)return;n.classList.toggle('ep43-big',!!state.largeText);n.classList.toggle('ep43-high',!!state.highContrast)}

function footer(){return `<p class="ep-foot">EduPlan AI ${VERSION} · ${E(AUTHOR)}. Sản phẩm chạy cục bộ; dùng mã giả lập, không có phân quyền máy chủ. Nội dung Hóa học và câu hỏi phải được giáo viên thẩm định trước khi sử dụng chính thức. Đối chiếu ý tưởng thiết kế với Azota, Khan Academy và PhET; không sử dụng mã nguồn của các bên này.</p>`}
function frame(){return `<div class="ep-shade" id="ep42shade" onclick="EDP42.closeMenu()"></div><div class="ep-shell"><aside class="ep-side" id="ep42side"><div class="ep-mark"><span class="ep-logo">⚗️</span><div><b>EduPlan AI 4.3</b><small>TRỢ LÝ HÓA HỌC THPT</small></div></div><span class="ep-side-label">TRUNG TÂM</span>${[['home','⌂','Tổng quan'],['tools','▦','Tất cả công cụ'],['diagnostic','🧭','Chẩn đoán hai lượt'],['plan','🗓️','Kế hoạch 7 ngày'],['evidence','📥','Tiếp nhận kết quả'],['simlab','🧪','Mô phỏng Hóa học'],['fix','🧠','Trạm sửa lỗi'],['reflection','💬','Phản tư 3–2–1'],['audit','🔎','Kiểm định ngân hàng']].filter(x=>!['audit','evidence'].includes(x[0])||teacher()).filter(x=>!['diagnostic','plan'].includes(x[0])||!teacher()).map(x=>`<button class="ep-nav ${state.view===x[0]?'ep-on':''}" onclick="EDP42.go('${x[0]}')">${x[1]} <span>${x[2]}</span></button>`).join('')}<span class="ep-side-label">TRUY CẬP NHANH</span>${widgets.filter(x=>x.role===state.role).slice(3,7).map(x=>`<button class="ep-nav" onclick="EDP42.launch('${x.id}')">${x.icon} <span>${E(x.name)}</span></button>`).join('')}<div class="ep-sidefoot"><b>${E(AUTHOR)}</b><br>576 câu hiện có · 11 nguồn CHEM-ERROR<br>Bản chạy thử cục bộ, giáo viên thẩm định nội dung.</div></aside><div class="ep-main"><div class="ep-top"><button class="ep-menu-toggle" onclick="EDP42.toggleMenu()" aria-label="Mở danh mục" aria-controls="ep42side">☰</button><div class="ep-top-name">KHÔNG GIAN DẠY VÀ HỌC HÓA HỌC</div><button class="ep-btn ep43-topbtn" onclick="EDP42.textSize()" aria-label="Tăng hoặc giảm cỡ chữ">A±</button><button class="ep-btn ep43-topbtn" onclick="EDP42.contrast()" aria-label="Đổi chế độ tương phản">◐</button><div class="ep-controls"><button class="ep-role ${teacher()?'ep-active':''}" onclick="EDP42.role('teacher')" aria-pressed="${teacher()}">Giáo viên</button><button class="ep-role ${!teacher()?'ep-active':''}" onclick="EDP42.role('student')" aria-pressed="${!teacher()}">Học sinh</button><select class="ep-grade" aria-label="Chọn khối lớp" onchange="EDP42.grade(this.value)">${['10','11','12'].map(g=>`<option value="${g}" ${state.grade===g?'selected':''}>Hóa ${g}</option>`).join('')}</select></div></div><div class="ep-body" id="ep42body"></div></div></div><div id="ep42-toast" hidden style="position:fixed;bottom:16px;left:50%;transform:translateX(-50%);background:#0d3a61;color:white;padding:12px 16px;z-index:10;border-radius:10px;font-size:13px"></div>`}
function render(){const root=$('ep42');if(!root)return;root.innerHTML=frame();$('ep42body').innerHTML=({home,tools,fix,audit,reflection,diagnostic:ep43Diagnostic,plan:ep43Plan,evidence:ep43Evidence,simlab:ep43Sim}[state.view]||home)()+footer();root.scrollTop=0;ep43ApplyAppearance()}
function go(v){if(['audit','evidence'].includes(v)&&!teacher())v='home';if(['diagnostic','plan'].includes(v)&&teacher())v='home';state.view=v;state.menu=false;render()}
window.EDP42={
 textSize(){state.largeText=!state.largeText;persist();ep43ApplyAppearance()},
 contrast(){state.highContrast=!state.highContrast;persist();ep43ApplyAppearance()},
 setStudyCode(v){state.studentCode=ep43Code(v);state.diag=null;persist();go(state.view)},
 diagLesson(id){state.diagLesson=id;state.diag=null;persist();go(state.view)},
 diagStart(){let l=ep43Lesson(),pool=ep43Pool(l?.id);if(pool.length<12){showToast('Bài học cần tối thiểu 12 câu khác nhau để tạo hai lượt.');return}state.diagLesson=l.id;state.diag={grade:state.grade,lessonId:l.id,stage:1,ids:ep43Select(pool,6).map(q=>q.id),answers:{},finished:false,createdAt:new Date().toISOString()};persist();go('diagnostic')},
 diagAnswer(id,v){if(!state.diag||state.diag.finished||!state.diag.ids.includes(id))return;state.diag.answers[id]=Number(v);persist();let panel=$('ep43AnswerStatus');if(panel)panel.textContent=Object.keys(state.diag.answers).length+' câu đã làm';let btn=document.querySelector('#ep43submit');if(btn){let ready=Object.keys(state.diag.answers).length===state.diag.ids.length;btn.disabled=!ready;if(ready)btn.textContent='Nộp lượt '+state.diag.stage}},
 diagSubmit(){let d=state.diag;if(!d||d.finished||d.grade!==state.grade)return;let qs=d.ids.map(id=>bank().find(q=>q.id===id));if(qs.some(q=>!q)||d.ids.some(id=>!Number.isInteger(d.answers[id]))){showToast('Hãy trả lời đủ số câu trước khi nộp.');return}let items=qs.map(q=>({id:q.id,lv:q.lv,right:d.answers[q.id]===q.ans})),correct=items.filter(x=>x.right).length,l=ep43Lesson();let rec={id:'ev-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),code:state.studentCode,grade:state.grade,lessonId:l.id,lesson:l.title,stage:d.stage,at:new Date().toISOString(),total:items.length,correct,items};state.diagnostics.push(rec);state.diagnostics=state.diagnostics.slice(-240);d.finished=true;d.resultId=rec.id;persist();go('diagnostic')},
 diagNext(){let d=state.diag;if(!d||!d.finished||d.stage!==1)return;let used=new Set(d.ids),pool=ep43Pool(d.lessonId).filter(q=>!used.has(q.id));if(pool.length<6){showToast('Bài chưa đủ 6 câu mới cho lượt hai.');return}let r=state.diagnostics.find(x=>x.id===d.resultId),weak=new Set((r?.items||[]).filter(x=>!x.right).map(x=>x.lv));pool.sort((a,b)=>Number(weak.has(b.lv))-Number(weak.has(a.lv)));let top=pool.filter(q=>weak.has(q.lv));let rest=pool.filter(q=>!weak.has(q.lv));let ids=[...ep43Select(top,Math.min(6,top.length)),...ep43Select(rest,Math.max(0,6-top.length))].slice(0,6).map(x=>x.id);state.diag={grade:state.grade,lessonId:d.lessonId,stage:2,ids,answers:{},finished:false,createdAt:new Date().toISOString()};persist();go('diagnostic')},
 diagExport(){let l=ep43Lesson(),list=state.diagnostics.filter(r=>r.grade===state.grade&&r.code===state.studentCode&&r.lessonId===l.id);if(!list.length){showToast('Chưa có kết quả để xuất');return}let rounds=list.slice(-2).map(r=>({stage:r.stage,at:r.at,total:r.total,correct:r.correct,items:r.items.map(x=>({id:x.id,lv:x.lv,right:!!x.right}))}));let ev={schema:ep43EvidenceSchema,id:'file-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),grade:state.grade,code:state.studentCode,lessonId:l.id,lesson:l.title,createdAt:new Date().toISOString(),rounds};DL('EduPlan43_Ket_qua_'+state.studentCode+'.json',JSON.stringify(ev,null,2));showToast('Đã xuất kết quả không kèm đáp án. Gửi tệp cho giáo viên.')},
 planBuild(){let k=ep43PlanKey(),current=state.plans.find(x=>x.key===k);if(current){current.tasks=[...ep43TaskBase];}else state.plans.push({key:k,done:Array(7).fill(false),tasks:[...ep43TaskBase]});persist();go('plan')},
 planCheck(i,v){let p=state.plans.find(x=>x.key===ep43PlanKey());if(!p||i<0||i>6)return;p.done[i]=!!v;persist();go('plan')},
 planExport(){let p=state.plans.find(x=>x.key===ep43PlanKey());if(!p)return;DL('EduPlan43_Ke_hoach_7_ngay.csv',csv([['Mã','Khối','Bài','Ngày','Nhiệm vụ','Hoàn thành'],...p.tasks.map((v,i)=>[state.studentCode,state.grade,ep43Lesson()?.title,i+1,v,p.done[i]?'Có':'Chưa'])]),'text/csv;charset=utf-8')},
 async evidenceImport(files){let ok=0,bad=0,seen=new Set(state.importedEvidence.map(x=>x.id));for(const f of Array.from(files||[]).slice(0,60)){try{if(f.size>150000)throw Error('Quá lớn');let x=JSON.parse(await f.text());if(x.schema!==ep43EvidenceSchema||typeof x.id!=='string'||x.id.length>100||!['10','11','12'].includes(String(x.grade))||!/^[-A-Z0-9_]{1,18}$/.test(x.code)||typeof x.lesson!=='string'||x.lesson.length>170||!Array.isArray(x.rounds)||x.rounds.length<1||x.rounds.length>2)throw Error('Sai tệp');for(let r of x.rounds){if(!Number.isInteger(r.total)||r.total<1||r.total>6||!Number.isInteger(r.correct)||r.correct<0||r.correct>r.total||!Array.isArray(r.items)||r.items.length!==r.total||!r.items.every(it=>typeof it.id==='string'&&it.id.length<90&&typeof it.lv==='string'&&it.lv.length<40&&typeof it.right==='boolean'))throw Error('Sai dữ liệu lượt làm')}if(!seen.has(x.id)){state.importedEvidence.push({...x,status:'Đã nhận',note:''});seen.add(x.id);ok++}}catch(e){bad++}}state.importedEvidence=state.importedEvidence.slice(-300);persist();go('evidence');showToast('Nhập '+ok+' tệp; bỏ qua '+bad+' tệp không hợp lệ.')},
 evidenceStatus(id,v){let e=state.importedEvidence.find(x=>x.id===id);if(e&&['Đã nhận','Cần xem lại','Cần hỗ trợ','Đã phản hồi'].includes(v)){e.status=v;persist();go('evidence')}},
 evidenceNote(id,v){let e=state.importedEvidence.find(x=>x.id===id);if(e){e.note=String(v).slice(0,240);persist()}},
 evidenceCSV(){const arr=state.importedEvidence.filter(x=>x.grade===state.grade);DL('EduPlan43_Bao_cao_tiep_nhan.csv',csv([['Khối','Mã học tập','Bài','Lượt','Điểm','Trạng thái','Nhận xét'],...arr.map(x=>[x.grade,x.code,x.lesson,x.rounds.length,x.rounds.map(r=>r.correct+'/'+r.total).join('; '),x.status,x.note||''])]),'text/csv;charset=utf-8')},
 simChoose(i){state.simPick=Number(i);go('simlab')},
 simSave(){let sims=ep43Sims.filter(x=>x.grade===state.grade),i=Number($('ep43SimPick')?.value||0),s=sims[i],p=String($('ep43Predict')?.value||'').trim(),o=String($('ep43Observe')?.value||'').trim(),ex=String($('ep43Explain')?.value||'').trim();if(!s||!p||!o||!ex){showToast('Hãy ghi đủ Dự đoán – Quan sát – Giải thích.');return}let note={schema:'EduPlan43_SimNote',id:'sim-'+Date.now().toString(36),grade:state.grade,code:state.studentCode,name:s.name,url:s.url,predict:p.slice(0,1200),observe:o.slice(0,1200),explain:ex.slice(0,1400),at:new Date().toISOString()};state.simNotes.push(note);state.simNotes=state.simNotes.slice(-120);persist();DL('EduPlan43_Phieu_mo_phong.json',JSON.stringify(note,null,2));go('simlab')},
 backup43(){DL('EduPlan43_Sao_luu.json',JSON.stringify({schema:'EduPlan43_Backup',version:'4.3',at:new Date().toISOString(),records:state.records,replies:state.replies,favorites:state.favorites,diagnostics:state.diagnostics,plans:state.plans,importedEvidence:state.importedEvidence,simNotes:state.simNotes,studentCode:state.studentCode},null,2))},
 async restore43(file){if(!file)return;try{if(file.size>3000000)throw Error('Tệp quá lớn');let x=JSON.parse(await file.text());if(x.schema!=='EduPlan43_Backup'||!Array.isArray(x.diagnostics)||!Array.isArray(x.plans)||!Array.isArray(x.importedEvidence)||!Array.isArray(x.simNotes))throw Error('Không đúng bản sao lưu 4.3');if(!confirm('Khôi phục sẽ thay dữ liệu học tập 4.3 hiện tại. Tiếp tục?'))return;state.diagnostics=x.diagnostics.slice(-240);state.plans=x.plans.slice(-120);state.importedEvidence=x.importedEvidence.slice(-300);state.simNotes=x.simNotes.slice(-120);state.records=Array.isArray(x.records)?x.records.slice(-800):state.records;state.replies=Array.isArray(x.replies)?x.replies.slice(-300):state.replies;state.studentCode=ep43Code(x.studentCode);persist();go('home');showToast('Đã khôi phục bản sao 4.3')}catch(e){showToast('Không thể khôi phục: '+e.message)}},

 version:VERSION, stats:()=>({bank:bank().length,lessons:lessons().length,repairRecords:state.records.length,reflections:state.replies.length}),
 go,home:()=>{let r=$('ep42');if(r)r.hidden=false;go('home')},
 role(v){state.role=v;try{window.edp35Role?.(v)}catch(e){}go('home')},
 grade(v){state.grade=String(v);state.lesson='';state.diag=null;state.diagLesson='';state.current=null;state.selected=null;state.check=false;let g=$('grade');if(g){g.value=v;g.dispatchEvent(new Event('change',{bubbles:true}))}go('home')},
 launch(id){if(['fix','audit','reflection','diagnostic','plan','evidence','simlab'].includes(id))return go(id);if(id==='ce'){ $('ep42').hidden=true;window.ceOpen?.();return }$('ep42').hidden=true;try{window.nav(id)}catch(e){$('ep42').hidden=false;showToast('Không mở được chức năng cũ, hãy chọn một mục khác.')}},
 toggleMenu(){state.menu=!state.menu;$('ep42side')?.classList.toggle('ep-open',state.menu);$('ep42shade')?.classList.toggle('ep-open',state.menu)},
 closeMenu(){state.menu=false;$('ep42side')?.classList.remove('ep-open');$('ep42shade')?.classList.remove('ep-open')},
 search(v){let n=$('epSearchCards');if(n)n.innerHTML=cards(toolsList(v).slice(0,8))},
 toolSearch(v){state.filter=v;let n=$('epToolCards');if(n)n.innerHTML=cards(toolsList(state.filter,state.category||'all'))},
 toolCategory(v){state.category=v;let n=$('epToolCards');if(n)n.innerHTML=cards(toolsList(state.filter,state.category||'all'))},
 lesson(id){state.lesson=id;state.current=null;state.selected=null;state.check=false;go('fix')},
 level(s){state.level=s;state.current=null;state.selected=null;state.check=false;go('fix')},
 newQuiz(){const p=qList();if(!p.length){showToast('Chưa có câu hỏi đủ điều kiện trong bộ lọc này.');return}const seen=new Set(state.records.filter(r=>r.grade===state.grade).map(r=>r.id));const un=p.filter(q=>!seen.has(q.id));let a=un.length?un:p;let q=a[state.questionIndex%a.length];state.questionIndex++;state.current=q;state.selected=null;state.check=false;go('fix')},
 answer(i){state.selected=Number(i);document.querySelector('#ep42Q button[onclick="EDP42.check()"]')?.removeAttribute('disabled')},
 check(){if(state.selected===null){showToast('Hãy chọn một phương án trước.');return}state.check=true;let n=$('ep42Q');if(n)n.innerHTML=question()},
 saveError(){if(!state.current||!state.check)return;let cause=$('ep42cause')?.value||'Chưa phân loại',q=state.current;state.records.push({schema:'ep42_repair',id:q.id,grade:q.g,lesson:q.lesson,level:q.lv,right:state.selected===q.ans,cause,at:new Date().toISOString()});state.records=state.records.slice(-800);persist();this.newQuiz()},
 exportJournal(){let xs=state.records.filter(x=>x.grade===state.grade);DL('EduPlan42_Nhat_ky_sua_loi.csv',csv([['Ngày','Mã câu','Khối','Bài','Mức','Đúng/Sai','Nguyên nhân'],...xs.map(x=>[x.at,x.id,x.grade,x.lesson,x.level,x.right?'Đúng':'Sai',x.cause])]),'text/csv;charset=utf-8')},
 auditFilter(v){state.auditFilter=v;go('audit')},
 exportAudit(){let rows=[['Mã câu','Khối','Chương','Bài','Phần','Mức','Nguồn','Trạng thái','Cảnh báo cấu trúc'],...inspectBank().map(x=>[x.q.id,x.q.g,x.q.chapter,x.q.lesson,x.q.type,x.q.lv,x.q.src||x.q.reference_url||'',x.q.review||'',x.flags.join('; ')])];DL('EduPlan42_Kiem_dinh_cau_hoi.csv',csv(rows),'text/csv;charset=utf-8')},
 saveReflection(){let l=L().find(x=>x.id===$('ep42rfLesson')?.value),know=threeLines($('ep42rfKnow')?.value||''),confusing=threeLines($('ep42rfConf')?.value||''),question=String($('ep42rfQuestion')?.value||'').trim();if(know.length!==3||confusing.length!==2||!question){showToast('Cần đúng 3 ý đã học, 2 ý còn băn khoăn và 1 câu hỏi.');return}let item={schema:'EduPlan_Reflection_3_2_1',id:'rf-'+Date.now().toString(36),grade:state.grade,lessonId:l.id,lesson:l.title,know:know.map(x=>x.slice(0,250)),confusing:confusing.map(x=>x.slice(0,250)),question:question.slice(0,350),date:new Date().toISOString().slice(0,10)};state.replies.push(item);persist();DL('Phan_tu_3_2_1_'+item.id+'.json',JSON.stringify(item,null,2));showToast('Đã xuất phiếu. Gửi file JSON cho giáo viên để tổng hợp.');go('reflection')},
 async importReplies(files){let ok=0,bad=0,seen=new Set(state.replies.map(x=>x.id));for(const f of Array.from(files||[]).slice(0,100)){try{if(f.size>50000)throw Error('Tệp quá lớn');let x=JSON.parse(await f.text());if(x.schema!=='EduPlan_Reflection_3_2_1'||!['10','11','12'].includes(String(x.grade))||!Array.isArray(x.know)||x.know.length!==3||!Array.isArray(x.confusing)||x.confusing.length!==2||typeof x.question!=='string'||x.question.length>350||typeof x.lesson!=='string'||x.lesson.length>180||typeof x.lessonId!=='string'||x.lessonId.length>80||typeof x.id!=='string'||x.id.length>80||!x.know.every(y=>typeof y==='string'&&y.length<=250)||!x.confusing.every(y=>typeof y==='string'&&y.length<=250))throw Error('Sai cấu trúc');if(!seen.has(x.id)){state.replies.push(x);seen.add(x.id);ok++}}catch(e){bad++}}state.replies=state.replies.slice(-300);persist();go('reflection');showToast(`Nhập ${ok} phiếu. Bỏ qua ${bad} tệp không hợp lệ hoặc quá lớn.`)},
 exportRepliesCSV(){let xs=state.replies.filter(x=>x.grade===state.grade);DL('EduPlan42_Phan_tu_3_2_1.csv',csv([['Ngày','Khối','Bài','3 điều đã hiểu','2 điều băn khoăn','1 câu hỏi'],...xs.map(x=>[x.date,x.grade,x.lesson,x.know.join('; '),x.confusing.join('; '),x.question])]),'text/csv;charset=utf-8')},
 exportBackup(){DL('EduPlan42_Sao_luu.json',JSON.stringify({schema:'EduPlan42',at:new Date().toISOString(),records:state.records,replies:state.replies,favorites:state.favorites,diagnostics:state.diagnostics,plans:state.plans,importedEvidence:state.importedEvidence,simNotes:state.simNotes,diag:state.diag,studentCode:state.studentCode,largeText:state.largeText,highContrast:state.highContrast},null,2))}
};
load();let node=document.createElement('div');node.id='ep42';node.setAttribute('aria-label','Trung tâm EduPlan AI 4.3');document.body.appendChild(node);let launcher=document.createElement('button');launcher.id='ep42-return';launcher.textContent='⌂ Trung tâm EduPlan 4.2';launcher.style.cssText='position:fixed;bottom:18px;right:18px;z-index:7999;background:#064c86;color:#fff;border:0;border-radius:14px;padding:12px 16px;box-shadow:0 7px 24px #102d4d3d;font-weight:800;cursor:pointer';launcher.onclick=()=>{$('ep42').hidden=false;window.ceClose?.();go('home')};document.body.appendChild(launcher);
document.addEventListener('keydown',e=>{if(e.key==='Escape')window.EDP42.closeMenu();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){if(!$('ep42').hidden){e.preventDefault();go('tools');$('epToolSearch')?.focus()}}});
render();document.title='EduPlan AI 4.3 – WebApp Hóa học THPT | Lê Bá Nhẫn';
})();

